//! Nginx virtual host template rendering powered by `minijinja`.

use crate::error::WebserverError;
use minijinja::Environment;
use panel_core::domain::DomainName;
use serde::{Deserialize, Serialize};

pub const STATIC_VHOST_TEMPLATE: &str = r#"# Nusa Panel - Site Virtual Host (Static)
# Site ID: {{ site_id }}
# Auto-generated by panel-webserver. Do not edit directly.

{% if force_https and has_ssl %}
server {
    listen 80;
    listen [::]:80;
    server_name {{ primary_domain }}{% for alias in alias_domains %} {{ alias }}{% endfor %};

    include {{ snippets_dir }}/acme.conf;

    location / {
        return 301 https://$host$request_uri;
    }
}
{% endif %}

server {
    {% if not force_https or not has_ssl %}
    listen 80;
    listen [::]:80;
    {% endif %}
    {% if has_ssl %}
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;
    ssl_certificate {{ ssl_cert }};
    ssl_certificate_key {{ ssl_key }};
    {% if ocsp_stapling %}
    ssl_stapling on;
    ssl_stapling_verify on;
    resolver 1.1.1.1 8.8.8.8 valid=300s;
    resolver_timeout 5s;
    {% endif %}
    {% endif %}

    server_name {{ primary_domain }}{% for alias in alias_domains %} {{ alias }}{% endfor %};

    root {{ docroot }};
    index {{ index_files | default("index.html index.htm") }};

    access_log {{ log_dir }}/access.log panel_json;
    error_log {{ log_dir }}/error.log warn;

    include {{ snippets_dir }}/acme.conf;
    include {{ snippets_dir }}/security-headers.conf;
    include {{ snippets_dir }}/deny-sensitive.conf;

    {% if custom_headers %}
    # Custom Headers
    {% for header in custom_headers %}
    add_header {{ header.name }} "{{ header.value }}" always;
    {% endfor %}
    {% endif %}

    # Static assets caching
    location ~* \.(?:css|js|jpg|jpeg|gif|png|ico|cur|gz|svg|svgz|mp4|ogg|ogv|webm|htc|woff|woff2|ttf|eot)$ {
        expires 30d;
        add_header Cache-Control "public, no-transform";
        access_log off;
        log_not_found off;
    }

    # Primary location handler
    location / {
        {% if spa_fallback %}
        try_files $uri $uri/ /index.html;
        {% else %}
        try_files $uri $uri/ =404;
        {% endif %}
    }
}

{% if redirects %}
# Domain Redirects (Alias / Subdomain / www / non-www / Custom)
{% for redir in redirects %}
server {
    listen 80;
    listen [::]:80;
    {% if has_ssl %}
    listen 443 ssl;
    listen [::]:443 ssl;
    http2 on;
    ssl_certificate {{ ssl_cert }};
    ssl_certificate_key {{ ssl_key }};
    {% endif %}

    server_name {{ redir.domain }};

    include {{ snippets_dir }}/acme.conf;

    location / {
        return {{ redir.status_code }} {{ redir.target }};
    }
}
{% endfor %}
{% endif %}
"#;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct HeaderConfig {
    pub name: String,
    pub value: String,
}

/// Redirection configuration for alias or auxiliary domains.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct DomainRedirectConfig {
    pub domain: String,
    pub target: String,
    pub status_code: u16,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct StaticVhostContext {
    pub site_id: String,
    pub primary_domain: String,
    pub alias_domains: Vec<String>,
    pub redirects: Vec<DomainRedirectConfig>,
    pub docroot: String,
    pub log_dir: String,
    pub snippets_dir: String,
    pub index_files: Option<String>,
    pub spa_fallback: bool,
    pub has_ssl: bool,
    pub ssl_cert: Option<String>,
    pub ssl_key: Option<String>,
    pub force_https: bool,
    pub ocsp_stapling: bool,
    pub custom_headers: Vec<HeaderConfig>,
}

pub struct NginxTemplateRenderer {
    env: Environment<'static>,
}

impl Default for NginxTemplateRenderer {
    fn default() -> Self {
        Self::new()
    }
}

impl NginxTemplateRenderer {
    pub fn new() -> Self {
        let mut env = Environment::new();
        // In minijinja, add template
        if let Err(e) = env.add_template("vhost_static", STATIC_VHOST_TEMPLATE) {
            tracing::error!("Failed to register static vhost template: {e}");
        }
        Self { env }
    }

    /// Renders a static website virtual host after validating all inputs against injection attacks.
    pub fn render_static(&self, ctx: &StaticVhostContext) -> Result<String, WebserverError> {
        validate_vhost_inputs(ctx)?;

        // Normalize paths for Nginx directives
        let mut normalized = ctx.clone();
        normalized.docroot = normalized.docroot.replace('\\', "/");
        normalized.log_dir = normalized.log_dir.replace('\\', "/");
        normalized.snippets_dir = normalized.snippets_dir.replace('\\', "/");
        if let Some(ref cert) = normalized.ssl_cert {
            normalized.ssl_cert = Some(cert.replace('\\', "/"));
        }
        if let Some(ref key) = normalized.ssl_key {
            normalized.ssl_key = Some(key.replace('\\', "/"));
        }

        let tmpl = self
            .env
            .get_template("vhost_static")
            .map_err(|e| WebserverError::Template(e.to_string()))?;

        tmpl.render(&normalized)
            .map_err(|e| WebserverError::Template(e.to_string()))
    }
}

/// Strictly validates all context fields against config injection attacks.
pub fn validate_vhost_inputs(ctx: &StaticVhostContext) -> Result<(), WebserverError> {
    // 1. Site ID validation
    if ctx.site_id.trim().is_empty() {
        return Err(WebserverError::SecurityViolation(
            "site_id cannot be empty".to_string(),
        ));
    }
    for ch in ctx.site_id.chars() {
        if !ch.is_alphanumeric() && ch != '-' && ch != '_' {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid character '{ch}' in site_id '{}'",
                ctx.site_id
            )));
        }
    }

    // 2. Domain validation (RFC 1034/1035 + Punycode IDN + forbidden chars)
    validate_domain_input(&ctx.primary_domain)?;
    for alias in &ctx.alias_domains {
        validate_domain_input(alias)?;
    }

    // 3. Docroot validation
    validate_path_input(&ctx.docroot, "docroot")?;
    validate_path_input(&ctx.log_dir, "log_dir")?;
    validate_path_input(&ctx.snippets_dir, "snippets_dir")?;

    if let Some(ref cert) = ctx.ssl_cert {
        validate_path_input(cert, "ssl_cert")?;
    }
    if let Some(ref key) = ctx.ssl_key {
        validate_path_input(key, "ssl_key")?;
    }

    // 4. Custom headers validation
    for h in &ctx.custom_headers {
        if !h
            .name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-')
        {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid HTTP header name: '{}'",
                h.name
            )));
        }
        if h.value
            .chars()
            .any(|c| c == '\n' || c == '\r' || c == '\0' || c == '"' || c == ';')
        {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid characters in HTTP header value: '{}'",
                h.value
            )));
        }
    }

    // 5. Redirects validation
    for r in &ctx.redirects {
        validate_domain_input(&r.domain)?;
        validate_redirect_target(&r.target)?;
        if r.status_code != 301
            && r.status_code != 302
            && r.status_code != 307
            && r.status_code != 308
        {
            return Err(WebserverError::SecurityViolation(format!(
                "Invalid redirect status code: {}",
                r.status_code
            )));
        }
    }

    Ok(())
}

fn validate_redirect_target(target: &str) -> Result<(), WebserverError> {
    const FORBIDDEN_CHARS: &[char] = &[
        ';', '{', '}', '\n', '\r', '\0', '"', '\'', ' ', '\t', '<', '>',
    ];
    for ch in FORBIDDEN_CHARS {
        if target.contains(*ch) {
            return Err(WebserverError::SecurityViolation(format!(
                "Redirect target '{target}' contains forbidden character '{ch}'"
            )));
        }
    }

    if !target.starts_with("http://")
        && !target.starts_with("https://")
        && !target.starts_with('/')
        && !target.starts_with("$scheme://")
    {
        return Err(WebserverError::SecurityViolation(format!(
            "Redirect target '{target}' must start with http://, https://, /, or $scheme://"
        )));
    }

    for (idx, _) in target.match_indices('$') {
        let remainder = &target[idx..];
        let allowed = remainder.starts_with("$request_uri")
            || remainder.starts_with("$host")
            || remainder.starts_with("$scheme");
        if !allowed {
            return Err(WebserverError::SecurityViolation(format!(
                "Unrecognized or forbidden variable in redirect target '{target}'"
            )));
        }
    }

    Ok(())
}

fn validate_domain_input(raw: &str) -> Result<(), WebserverError> {
    // Check forbidden control & Nginx configuration characters
    const FORBIDDEN_CHARS: &[char] = &[';', '{', '}', '$', '\n', '\r', '\0', '"', ' ', '\t'];
    for ch in FORBIDDEN_CHARS {
        if raw.contains(*ch) {
            return Err(WebserverError::SecurityViolation(format!(
                "Domain '{raw}' contains forbidden character '{ch}'"
            )));
        }
    }

    // Parse and validate via DomainName (RFC compliance & IDN normalization)
    DomainName::parse(raw)
        .map_err(|e| WebserverError::SecurityViolation(format!("Invalid domain '{raw}': {e}")))?;

    Ok(())
}

fn validate_path_input(raw: &str, field_name: &str) -> Result<(), WebserverError> {
    if raw.trim().is_empty() {
        return Err(WebserverError::SecurityViolation(format!(
            "{field_name} cannot be empty"
        )));
    }

    const FORBIDDEN_CHARS: &[char] = &[';', '{', '}', '$', '\n', '\r', '\0', '"'];
    for ch in FORBIDDEN_CHARS {
        if raw.contains(*ch) {
            return Err(WebserverError::SecurityViolation(format!(
                "Path in {field_name} contains forbidden character '{ch}'"
            )));
        }
    }

    Ok(())
}

/// Generates a modern, responsive placeholder HTML page for newly created sites.
