#[cfg(test)]
#[allow(clippy::unwrap_used, clippy::expect_used)]
mod tests {
    use super::*;

    #[test]
    fn test_golden_static_vhost_http_only() {
        let renderer = NginxTemplateRenderer::new();
        let ctx = StaticVhostContext {
            site_id: "site_static_1".to_string(),
            primary_domain: "example.com".to_string(),
            alias_domains: vec!["www.example.com".to_string()],
            docroot: "/home/p_alice/sites/example.com/public".to_string(),
            log_dir: "/var/log/panel/p_alice/example.com".to_string(),
            snippets_dir: "/etc/panel/nginx/snippets".to_string(),
            index_files: Some("index.html index.htm".to_string()),
            spa_fallback: false,
            has_ssl: false,
            ssl_cert: None,
            ssl_key: None,
            force_https: false,
            ocsp_stapling: false,
            custom_headers: vec![],
            redirects: vec![],
        };

        let conf = renderer.render_static(&ctx).expect("render static");
        assert!(conf.contains("server_name example.com www.example.com;"));
        assert!(conf.contains("root /home/p_alice/sites/example.com/public;"));
        assert!(conf.contains("try_files $uri $uri/ =404;"));
        assert!(conf.contains("include /etc/panel/nginx/snippets/security-headers.conf;"));
        assert!(conf.contains("include /etc/panel/nginx/snippets/deny-sensitive.conf;"));
        assert!(!conf.contains("listen 443 ssl;"));
    }

    #[test]
    fn test_golden_static_vhost_with_ssl_and_spa() {
        let renderer = NginxTemplateRenderer::new();
        let ctx = StaticVhostContext {
            site_id: "site_spa_2".to_string(),
            primary_domain: "my-app.id".to_string(),
            alias_domains: vec![],
            redirects: vec![],
            docroot: "/home/p_bob/sites/my-app.id/dist".to_string(),
            log_dir: "/var/log/panel/p_bob/my-app.id".to_string(),
            snippets_dir: "/etc/panel/nginx/snippets".to_string(),
            index_files: None,
            spa_fallback: true,
            has_ssl: true,
            ssl_cert: Some("/var/lib/panel/certs/my-app.id/fullchain.pem".to_string()),
            ssl_key: Some("/var/lib/panel/certs/my-app.id/privkey.pem".to_string()),
            force_https: true,
            ocsp_stapling: true,
            custom_headers: vec![HeaderConfig {
                name: "X-App-Framework".to_string(),
                value: "Vite-React".to_string(),
            }],
        };

        let conf = renderer.render_static(&ctx).expect("render spa with ssl");
        assert!(conf.contains("return 301 https://$host$request_uri;"));
        assert!(conf.contains("listen 443 ssl;"));
        assert!(conf.contains("ssl_certificate /var/lib/panel/certs/my-app.id/fullchain.pem;"));
        assert!(conf.contains("ssl_certificate_key /var/lib/panel/certs/my-app.id/privkey.pem;"));
        assert!(conf.contains("ssl_stapling on;"));
        assert!(conf.contains("try_files $uri $uri/ /index.html;"));
        assert!(conf.contains("add_header X-App-Framework \"Vite-React\" always;"));
    }

    #[test]
    fn test_golden_static_vhost_with_domain_redirects() {
        let renderer = NginxTemplateRenderer::new();
        let ctx = StaticVhostContext {
            site_id: "site_redir_3".to_string(),
            primary_domain: "example.com".to_string(),
            alias_domains: vec!["alias.com".to_string()],
            redirects: vec![
                DomainRedirectConfig {
                    domain: "www.example.com".to_string(),
                    target: "https://example.com$request_uri".to_string(),
                    status_code: 301,
                },
                DomainRedirectConfig {
                    domain: "old-domain.com".to_string(),
                    target: "https://example.com$request_uri".to_string(),
                    status_code: 301,
                },
                DomainRedirectConfig {
                    domain: "promo.example.com".to_string(),
                    target: "https://landing.com/promo".to_string(),
                    status_code: 302,
                },
            ],
            docroot: "/home/p_alice/sites/example.com/public".to_string(),
            log_dir: "/var/log/panel/p_alice/example.com".to_string(),
            snippets_dir: "/etc/panel/nginx/snippets".to_string(),
            index_files: None,
            spa_fallback: false,
            has_ssl: true,
            ssl_cert: Some("/var/lib/panel/certs/example.com/fullchain.pem".to_string()),
            ssl_key: Some("/var/lib/panel/certs/example.com/privkey.pem".to_string()),
            force_https: true,
            ocsp_stapling: false,
            custom_headers: vec![],
        };

        let conf = renderer.render_static(&ctx).expect("render with redirects");
        assert!(conf.contains("server_name example.com alias.com;"));
        assert!(conf.contains("server_name www.example.com;"));
        assert!(conf.contains("return 301 https://example.com$request_uri;"));
        assert!(conf.contains("server_name old-domain.com;"));
        assert!(conf.contains("server_name promo.example.com;"));
        assert!(conf.contains("return 302 https://landing.com/promo;"));
    }

    #[test]
    fn test_anti_injection_rejects_malicious_domains() {
        let renderer = NginxTemplateRenderer::new();
        let malicious_domains = vec![
            "example.com; return 403;",
            "evil.com\nserver { listen 8888; }",
            "evil.com\r\nlocation / { proxy_pass http://attacker; }",
            "test.com{root /;}",
            "attacker.com$document_root",
            "foo.com\"evil",
            "foo bar.com",
            "evil.com\0payload",
        ];

        for bad in malicious_domains {
            let ctx = StaticVhostContext {
                site_id: "site_test".to_string(),
                primary_domain: bad.to_string(),
                alias_domains: vec![],
                redirects: vec![],
                docroot: "/home/p_alice/public".to_string(),
                log_dir: "/var/log/panel/site".to_string(),
                snippets_dir: "/etc/panel/nginx/snippets".to_string(),
                index_files: None,
                spa_fallback: false,
                has_ssl: false,
                ssl_cert: None,
                ssl_key: None,
                force_https: false,
                ocsp_stapling: false,
                custom_headers: vec![],
            };

            let err = renderer.render_static(&ctx);
            assert!(
                err.is_err(),
                "Malicious domain '{}' should have been rejected!",
                bad
            );
        }
    }

    #[test]
    fn test_anti_injection_rejects_malicious_paths() {
        let renderer = NginxTemplateRenderer::new();
        let malicious_paths = vec![
            "/var/www; rm -rf /",
            "/var/www\naccess_log /dev/null;",
            "/var/www{root /;}",
            "/var/www$args",
        ];

        for bad_path in malicious_paths {
            let ctx = StaticVhostContext {
                site_id: "site_test".to_string(),
                primary_domain: "valid-site.com".to_string(),
                alias_domains: vec![],
                redirects: vec![],
                docroot: bad_path.to_string(),
                log_dir: "/var/log/panel/site".to_string(),
                snippets_dir: "/etc/panel/nginx/snippets".to_string(),
                index_files: None,
                spa_fallback: false,
                has_ssl: false,
                ssl_cert: None,
                ssl_key: None,
                force_https: false,
                ocsp_stapling: false,
                custom_headers: vec![],
            };

            let err = renderer.render_static(&ctx);
            assert!(
                err.is_err(),
                "Malicious docroot '{}' should have been rejected!",
                bad_path
            );
        }
    }

    #[test]
    fn test_anti_injection_rejects_malicious_redirect_targets() {
        let renderer = NginxTemplateRenderer::new();
        let malicious_targets = vec![
            "https://evil.com; return 403;",
            "https://evil.com\nserver { listen 80; }",
            "https://evil.com$document_root",
            "javascript:alert(1)",
            "ftp://not-http.com",
            "https://evil.com\"foo",
            "https://evil.com'bar",
            "https://evil.com/path with spaces",
        ];

        for bad_target in malicious_targets {
            let ctx = StaticVhostContext {
                site_id: "site_test".to_string(),
                primary_domain: "valid-site.com".to_string(),
                alias_domains: vec![],
                redirects: vec![DomainRedirectConfig {
                    domain: "redirect.valid-site.com".to_string(),
                    target: bad_target.to_string(),
                    status_code: 301,
                }],
                docroot: "/home/p_alice/public".to_string(),
                log_dir: "/var/log/panel/site".to_string(),
                snippets_dir: "/etc/panel/nginx/snippets".to_string(),
                index_files: None,
                spa_fallback: false,
                has_ssl: false,
                ssl_cert: None,
                ssl_key: None,
                force_https: false,
                ocsp_stapling: false,
                custom_headers: vec![],
            };

            let err = renderer.render_static(&ctx);
            assert!(
                err.is_err(),
                "Malicious redirect target '{}' should have been rejected!",
                bad_target
            );
        }
    }
}
